import { InvalidCacheNameError, InvalidConfigurationKeyError, InvalidServiceNameError } from './errors.js';

/** Largest wrapped DEK, in bytes, read from a key file or generated by a key wrapper. */
export const MAX_WRAPPED_KEY_BYTES = 512;

/** Consecutive failed refreshes tolerated before a provider fails closed, unless configured otherwise. */
export const DEFAULT_MAX_REFRESH_FAILURES = 3;

/** The prefix every configuration purpose starts with. */
export const CONFIGURATION_PURPOSE_PREFIX = 'HkdfGuard.EncryptedConfiguration';

/** The prefix of every protected-cache entry's AAD; key rings refuse protector names starting with it. */
export const CACHE_AAD_PREFIX = 'HkdfGuard.Cache:';

/** Longest service name, in characters. */
export const MAX_SERVICE_NAME_LENGTH = 128;

const encoder = new TextEncoder();

/** True if `s` holds no unpaired surrogate - valid UTF-16, so it has exactly one UTF-8 encoding. */
export function isWellFormed(s: string): boolean {
  return s.isWellFormed();
}

/** `s` with the ASCII letters a-z upper-cased and every other code unit left as it is. */
function upperAscii(s: string): string {
  return s.replace(/[a-z]+/g, (letters) => letters.toUpperCase());
}

/**
 * The purpose binding an encrypted configuration value to the configuration key it's stored under -
 * the single rule whoever writes a value (a pipeline) and whoever reads it must both derive, so a
 * value copied to a different key fails authentication. Every port implements it identically:
 * {@link CONFIGURATION_PURPOSE_PREFIX} + ":" + key, with the ASCII letters a-z upper-cased and every
 * other character left exactly as it is. Keys differing only in ASCII case share a purpose;
 * "café" and "CAFÉ" never do.
 *
 * @throws InvalidConfigurationKeyError the key is empty or holds an unpaired surrogate.
 */
export function configurationPurpose(configurationKey: string): string {
  if (configurationKey.length === 0) {
    throw new InvalidConfigurationKeyError('The configuration key must not be empty.');
  }
  if (!isWellFormed(configurationKey)) {
    throw new InvalidConfigurationKeyError('The configuration key is not valid UTF-16 (it holds an unpaired surrogate).');
  }
  return `${CONFIGURATION_PURPOSE_PREFIX}:${upperAscii(configurationKey)}`;
}

/** {@link configurationPurpose} as UTF-8 bytes - the AAD a configuration value is encrypted with. */
export function configurationAad(configurationKey: string): Uint8Array {
  return encoder.encode(configurationPurpose(configurationKey));
}

/**
 * The AAD a protected-cache entry stored under `name` is bound to: the UTF-8 bytes of
 * {@link CACHE_AAD_PREFIX} + name, with the ASCII letters a-z upper-cased - the same rule, and the
 * same matching, every port uses.
 *
 * @throws InvalidCacheNameError the name holds an unpaired surrogate.
 */
export function cacheAad(name: string): Uint8Array {
  if (!isWellFormed(name)) {
    throw new InvalidCacheNameError('The cache name is not valid UTF-16 (it holds an unpaired surrogate).');
  }
  return encoder.encode(CACHE_AAD_PREFIX + upperAscii(name));
}

/** The key a protected cache stores `name` under: matches exactly the names that share its AAD. */
export function cacheMatchKey(name: string): string {
  return upperAscii(name);
}

/**
 * Why `name` is not a valid service name - the identity of a KEK in the native KMS library: 1 to
 * {@link MAX_SERVICE_NAME_LENGTH} characters, each an ASCII letter, digit or '.', not starting with
 * '.' and never containing "..". Returns undefined for a valid name. The messages match every
 * other port's.
 */
export function serviceNameProblem(name: string | undefined | null): string | undefined {
  if (name === undefined || name === null || name.length === 0) {
    return 'A service name is required.';
  }
  if (name.length > MAX_SERVICE_NAME_LENGTH) {
    return `A service name is at most ${MAX_SERVICE_NAME_LENGTH} characters; this one is ${name.length}.`;
  }
  if (name[0] === '.') {
    return "A service name can't start with '.'.";
  }
  for (let i = 0; i < name.length; i++) {
    const c = name.charCodeAt(i);
    if (c === 0x2e) {
      if (name.charCodeAt(i - 1) === 0x2e) {
        return "A service name can't contain '..'.";
      }
    } else if (!(c >= 0x30 && c <= 0x39) && !(c >= 0x41 && c <= 0x5a) && !(c >= 0x61 && c <= 0x7a)) {
      return `A service name may contain only ASCII letters, digits and '.'; it has U+${c.toString(16).toUpperCase().padStart(4, '0')} at position ${i}.`;
    }
  }
  return undefined;
}

/** True if `name` satisfies every service-name rule. */
export function isValidServiceName(name: string | undefined | null): boolean {
  return serviceNameProblem(name) === undefined;
}

/**
 * Checks `name` against the service-name rules - before any native call, so a bad name fails with a
 * clear message and never crosses the boundary.
 *
 * @throws InvalidServiceNameError naming the rule broken.
 */
export function validateServiceName(name: string | undefined | null): asserts name is string {
  const problem = serviceNameProblem(name);
  if (problem !== undefined) {
    throw new InvalidServiceNameError(problem);
  }
}

/**
 * Zeroes every byte of `buffer`. Node has no pinned memory: zeroing is best-effort, reaching the
 * buffer's own bytes but not copies V8 or OpenSSL may have made. Keep secrets in buffers you
 * allocated with `Buffer.alloc` or `new Uint8Array` (never `Buffer.allocUnsafe`, which shares a
 * pool, and never a string, which can't be zeroed) and wipe them as soon as they are done with.
 */
export function wipe(buffer: Uint8Array | undefined): void {
  buffer?.fill(0);
}

/** True if `buffer` is empty or every byte is zero, in time that depends only on its length. */
export function isZero(buffer: Uint8Array): boolean {
  let accumulator = 0;
  for (const byte of buffer) {
    accumulator |= byte;
  }
  return accumulator === 0;
}
